-- Час задачі (HH:MM, Київ) → подія в Google Календарі на цей час з нагадуваннями за 2 год і 1 год
ALTER TABLE tasks ADD COLUMN due_time TEXT;
INSERT INTO changelog (title, body, created_at) VALUES ('Календар: задача з часом і нагадуваннями', 'У задачі поруч з дедлайном тепер є час (напр. 19:00). Якщо він стоїть (або є в назві — «до 19:00»), подія в Google Календарі ставиться саме на цей час, з нагадуваннями за 2 год і за 1 год. Без часу — як раніше, подія на весь день з нагадуванням напередодні. Помилка «Нема доступу до Календаря» тепер каже точну причину: вимкнений Google Calendar API у Google Cloud (з посиланням, де ввімкнути) або при підключенні не поставили галочку календаря. Джері: task_to_calendar приймає time і remind_minutes, create/update_task — due_time.', datetime('now'));
